import secrets
from flask import session, abort, render_template_string

def install(application):
    from app import can_edit
    def crop_editor():
        if not can_edit():
            abort(403)
        return render_template_string(PAGE, csrf=session.setdefault('csrf', secrets.token_urlsafe(32)))
    application.view_functions['artwork_editor'] = crop_editor
    def allow_local_preview(response):
        policy = response.headers.get('Content-Security-Policy', '')
        if policy and "blob:" not in policy:
            response.headers['Content-Security-Policy'] = policy.replace("img-src 'self' https://res.cloudinary.com", "img-src 'self' blob: https://res.cloudinary.com")
        return response
    application.after_request_funcs.setdefault(None, []).insert(0, allow_local_preview)

PAGE = '''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Crop artwork</title><style>*{box-sizing:border-box}body{font:15px Arial;background:#d8f0e5;color:#34564e;padding:20px}main{max-width:800px;margin:auto;background:#fffaf6;border:2px solid #75a18c;border-radius:22px;padding:24px}button,a{display:inline-block;margin:8px 6px 8px 0;padding:12px;border:1px solid #ae5980;border-radius:10px;background:#ffd4e5;color:#63394c;cursor:pointer}button:disabled{opacity:.5;cursor:default}label{display:block;line-height:1.8;margin:14px 0}input[type=file]{max-width:100%}canvas{display:block;max-width:100%;height:auto;background:#e4e4e4;margin:16px auto;border:1px solid #729b87}#stage{touch-action:none;cursor:crosshair;width:100%}#result{max-width:300px;max-height:350px;object-fit:contain}.numbers{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.numbers input{display:block;width:100%;padding:9px;font:inherit}#status{line-height:1.8;white-space:pre-wrap}[hidden]{display:none!important}</style></head><body><main><h1>Crop your artwork ♡</h1><p>Choose a new image or load the saved artwork. Drag across the image to select any rectangular crop. Use the pixel fields to fine-tune it. Nothing is published until you press Save.</p><p>To show the exact crop without extra trimming, choose “Show entire image” under Image fit in the page settings.</p><label>New artwork (PNG, JPG, WebP; under 5 MB)<input id="file" type="file" accept="image/png,image/jpeg,image/webp"></label><button type="button" id="current">Load saved artwork</button><section id="tools" hidden><canvas id="stage" width="720" height="450" aria-label="Artwork crop selection. Alternatively enter crop coordinates in the fields below."></canvas><button type="button" id="reset">Select whole image</button><button type="button" id="rotate">Rotate 90°</button><div class="numbers"><label>Left (pixels)<input type="number" id="x" min="0" step="1"></label><label>Top (pixels)<input type="number" id="y" min="0" step="1"></label><label>Width (pixels)<input type="number" id="w" min="1" step="1"></label><label>Height (pixels)<input type="number" id="h" min="1" step="1"></label></div><h2>Cropped preview</h2><canvas id="result" width="300" height="200" aria-label="Preview of the selected crop"></canvas><p id="dimensions"></p><form id="form"><label><input type="checkbox" id="permission" required> I own this artwork or have permission to publish it publicly.</label><button id="save" type="submit">Save cropped image for everyone</button></form><p>Cropping replaces the shared image. Keep your original file if you want to restore areas outside the crop later. Large crops are resized to fit within 2000 × 2000 pixels.</p></section><p id="status" role="status" aria-live="polite"></p><a href="/editor">Back to page settings</a><a href="/" target="_blank" rel="noopener">View website ↗</a></main><script>
const $=id=>document.getElementById(id),stage=$('stage'),ctx=stage.getContext('2d'),result=$('result'),rc=result.getContext('2d'),status=$('status');
let source=null,rect=null,drag=null,busy=false,loading=false,sequence=0;
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
function full(){rect={x:0,y:0,w:source.width,h:source.height};paint()}
function paint(){if(!source||!rect)return;rect.x=clamp(Math.round(rect.x),0,source.width-1);rect.y=clamp(Math.round(rect.y),0,source.height-1);rect.w=clamp(Math.round(rect.w),1,source.width-rect.x);rect.h=clamp(Math.round(rect.h),1,source.height-rect.y);for(const k of ['x','y','w','h'])$(k).value=rect[k];$('x').max=source.width-1;$('y').max=source.height-1;$('w').max=source.width-rect.x;$('h').max=source.height-rect.y;const scale=Math.min(720/source.width,500/source.height);stage.width=Math.max(1,Math.round(source.width*scale));stage.height=Math.max(1,Math.round(source.height*scale));const sx=stage.width/source.width,sy=stage.height/source.height;ctx.drawImage(source,0,0,stage.width,stage.height);ctx.fillStyle='rgba(0,0,0,.5)';ctx.fillRect(0,0,stage.width,stage.height);ctx.save();ctx.beginPath();ctx.rect(rect.x*sx,rect.y*sy,rect.w*sx,rect.h*sy);ctx.clip();ctx.drawImage(source,0,0,stage.width,stage.height);ctx.restore();ctx.strokeStyle='#ff65a0';ctx.lineWidth=3;ctx.strokeRect(rect.x*sx,rect.y*sy,rect.w*sx,rect.h*sy);const p=Math.min(300/rect.w,350/rect.h,1);result.width=Math.max(1,Math.round(rect.w*p));result.height=Math.max(1,Math.round(rect.h*p));rc.drawImage(source,rect.x,rect.y,rect.w,rect.h,0,0,result.width,result.height);$('dimensions').textContent='Selected crop: '+rect.w+' × '+rect.h+' pixels';}
function point(e){const b=stage.getBoundingClientRect();return{x:clamp((e.clientX-b.left)/b.width*source.width,0,source.width),y:clamp((e.clientY-b.top)/b.height*source.height,0,source.height)}}
stage.onpointerdown=e=>{if(!source||busy||loading)return;e.preventDefault();stage.setPointerCapture(e.pointerId);drag=point(e);rect={x:Math.min(drag.x,source.width-1),y:Math.min(drag.y,source.height-1),w:1,h:1};paint()};
stage.onpointermove=e=>{if(!drag)return;e.preventDefault();const p=point(e);rect={x:Math.min(drag.x,p.x),y:Math.min(drag.y,p.y),w:Math.max(1,Math.abs(p.x-drag.x)),h:Math.max(1,Math.abs(p.y-drag.y))};paint()};
stage.onpointerup=stage.onpointercancel=()=>{drag=null};
for(const k of ['x','y','w','h'])$(k).onchange=()=>{if(source&&!busy&&!loading){const n=Number($(k).value);if(Number.isFinite(n))rect[k]=n;paint()}};
$('reset').onclick=()=>{if(source&&!busy&&!loading)full()};
$('rotate').onclick=()=>{if(!source||busy||loading)return;const c=document.createElement('canvas');c.width=source.height;c.height=source.width;const x=c.getContext('2d');x.translate(c.width,0);x.rotate(Math.PI/2);x.drawImage(source,0,0);source=c;full()};
async function loadImage(url,remote=false){if(busy)return;const ticket=++sequence;loading=true;$('save').disabled=true;status.textContent='Loading image…';try{const image=new Image();if(remote)image.crossOrigin='anonymous';await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=()=>reject(new Error('Cannot open image. Try uploading the original PNG, JPG, or WebP.'));image.src=url});if(ticket!==sequence)return;if(image.naturalWidth*image.naturalHeight>15000000)throw new Error('Choose an image with no more than 15 million pixels.');const c=document.createElement('canvas');c.width=image.naturalWidth;c.height=image.naturalHeight;c.getContext('2d').drawImage(image,0,0);source=c;$('tools').hidden=false;full();status.textContent='Drag to select your crop, or adjust the pixel fields.'}catch(e){if(ticket===sequence)status.textContent=e.message}finally{if(!remote)URL.revokeObjectURL(url);if(ticket===sequence){loading=false;$('save').disabled=false}}}
$('file').onchange=()=>{if(busy)return;const f=$('file').files[0];if(!f)return;if(f.size>5*1024*1024||!['image/png','image/jpeg','image/webp'].includes(f.type)){status.textContent='Choose a PNG, JPG, or WebP under 5 MB.';return}loadImage(URL.createObjectURL(f))};
$('current').onclick=async()=>{if(busy||loading)return;try{status.textContent='Finding saved artwork…';const r=await fetch('/api/public-artwork'),d=await r.json();if(!r.ok||!d.url)throw new Error('No saved image could be loaded. Upload your original file instead.');const u=new URL(d.url);if(u.protocol!=='https:'||u.hostname!=='res.cloudinary.com')throw new Error('Unexpected image address.');await loadImage(u.href,true)}catch(e){status.textContent=e.message}};
$('form').onsubmit=async e=>{e.preventDefault();if(!source||busy||loading)return;if(!$('permission').checked){status.textContent='Confirm permission to publish first.';return}busy=true;const disabled=[];document.querySelectorAll('button,input').forEach(el=>{disabled.push([el,el.disabled]);el.disabled=true});status.textContent='Saving cropped image… Please keep this page open.';try{const c=document.createElement('canvas'),scale=Math.min(1,2000/rect.w,2000/rect.h);c.width=Math.max(1,Math.round(rect.w*scale));c.height=Math.max(1,Math.round(rect.h*scale));c.getContext('2d').drawImage(source,rect.x,rect.y,rect.w,rect.h,0,0,c.width,c.height);let blob=await new Promise(resolve=>c.toBlob(resolve,'image/png'));if(!blob)throw new Error('Cannot export this crop. Try uploading the original file.');if(blob.size>5*1024*1024){blob=await new Promise(resolve=>c.toBlob(resolve,'image/webp',.92));if(!blob||blob.size>5*1024*1024)throw new Error('Cropped image is still too large. Try a smaller crop.')}const data=new FormData();data.append('csrf',{{ csrf|tojson }});data.append('permission','yes');data.append('artwork',blob,blob.type==='image/webp'?'crop.webp':'crop.png');const r=await fetch('/api/artwork',{method:'POST',body:data});let d;try{d=await r.json()}catch(e){throw new Error('Unexpected server response. Check that you are still signed in.')}if(!r.ok)throw new Error(d.error||'Saving failed.');status.textContent='Saved for everyone! Reload the website to see your crop.'}catch(e){status.textContent=e.message}finally{busy=false;disabled.forEach(([el,was])=>el.disabled=was)}};
</script></body></html>'''
